# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HABEŞİSTAN HİCRETİ (615-616) VE NEJÂŞÎ ASHAME (PH.7.2.1)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Hicretin Nedenleri ve Aşamaları</text>\n  <text x="44" y="98" font-size="11" fill="#334155">• Neden: Mekkeli müşriklerin sahabilere</text>\n  <text x="44" y="114" font-size="11" fill="#334155">  yönelik baskı ve işkencelerinin artması</text>\n  <text x="44" y="138" font-size="11" fill="#334155">• Peygamberimizin Tavsiyesi: "Habeşistan\'da</text>\n  <text x="44" y="154" font-size="11" fill="#334155">  yanında kimseye zulmedilmeyen ADİL</text>\n  <text x="44" y="170" font-size="11" fill="#334155">  bir hükümdar (Necâşî) vardır."</text>\n  <text x="44" y="194" font-size="11" fill="#334155">• Birinci Kafile (615): 11 erkek, 4 kadın</text>\n  <text x="44" y="212" font-size="11" fill="#334155">  (Hz. Osman ve Hz. Rukiyye öncülüğünde)</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. İkinci Kafile ve Necâşî\'nin Adaleti</text>\n  <text x="378" y="98" font-size="11" fill="#334155">• İkinci Kafile (616): Ca\'fer bin Ebî Tâlib</text>\n  <text x="378" y="114" font-size="11" fill="#334155">  başkanlığında yaklaşık 90-100 muhacir</text>\n  <text x="378" y="138" font-size="11" fill="#334155">• Müşrik Elçileri: Amr bin Âs ve Abdullah</text>\n  <text x="378" y="154" font-size="11" fill="#334155">  bin Ebî Rebîa hediyelerle iade ister</text>\n  <text x="378" y="178" font-size="11" fill="#334155">• Necâşî Ashame: Muhacirleri dinlemeden</text>\n  <text x="378" y="194" font-size="11" fill="#334155">  teslim etmeyi reddeder ve onlara</text>\n  <text x="378" y="212" font-size="11" font-weight="bold" fill="#166534">  tam güvence (eman) verir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CA\'FER BİN EBÎ TÂLİB\'İN (RA) HABEŞ HÜKÜMDARI ÖNÜNDEKİ KONUŞMASI</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Cahiliye Dönemi Karanlığı</text>\n  <text x="44" y="98" font-size="11" fill="#334155">"Ey Hükümdar! Biz cahiliye ehli bir</text>\n  <text x="44" y="114" font-size="11" fill="#334155">kavimdik:"</text>\n  <text x="44" y="138" font-size="11" fill="#334155">• Putlara tapar, ölü hayvan eti yerdik</text>\n  <text x="44" y="158" font-size="11" fill="#334155">• Akrabalık bağlarını (sıla-i rahim) keserdik</text>\n  <text x="44" y="178" font-size="11" fill="#334155">• Komşuluk haklarını gözetmezdik</text>\n  <text x="44" y="198" font-size="11" fill="#334155">• Güçlü olanımız zayıf olanı ezerdi</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">İslam ve Hz. Peygamber\'in Getirdiği Aydınlık</text>\n  <text x="378" y="98" font-size="11" fill="#334155">"Allah içimizden soyunu, doğruluğunu ve</text>\n  <text x="378" y="114" font-size="11" fill="#334155">emanetini bildiğimiz bir elçi gönderdi:"</text>\n  <text x="378" y="138" font-size="11" fill="#334155">• Bize Allah\'ı birlemeyi (tevhit) emretti</text>\n  <text x="378" y="158" font-size="11" fill="#334155">• Doğru sözlü olmayı ve emaneti korumayı,</text>\n  <text x="378" y="178" font-size="11" fill="#334155">• Akrabayı ve komşuyu gözetmeyi öğretti</text>\n  <text x="378" y="202" font-size="11" font-weight="bold" fill="#92400e">• Okunan Sure: Meryem Suresi ilk ayetleri</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HZ. HAMZA VE HZ. ÖMER\'İN MÜSLÜMAN OLUŞU (NÜBÜVVETİN 6. YILI)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Hz. Hamza\'nın (ra) Müslüman Oluşu</text>\n  <text x="44" y="98" font-size="11" fill="#334155">• Kimliği: Peygamberimizin amcası ve</text>\n  <text x="44" y="114" font-size="11" fill="#334155">  süt kardeşi; Kureyş\'in cesur yiğidi</text>\n  <text x="44" y="138" font-size="11" fill="#334155">• Olay: Ebu Cehil\'in Safa tepesinde</text>\n  <text x="44" y="154" font-size="11" fill="#334155">  Hz. Peygamber\'e hakaret etmesi üzerine</text>\n  <text x="44" y="170" font-size="11" fill="#334155">  yeğenini koruyup İslam\'ı ilan etmesi</text>\n  <text x="183" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Lakapları: Esedullah (Allah\'ın Arslanı)</text>\n  <text x="183" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">ve Seyyidü\'ş-Şühedâ (Şehitlerin Efendisi)</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Hz. Ömer\'in (ra) Müslüman Oluşu</text>\n  <text x="378" y="98" font-size="11" fill="#334155">• Peygamberimizin Duası: "Allah\'ım! İslam\'ı</text>\n  <text x="378" y="114" font-size="11" fill="#334155">  Ömer bin Hattâb veya Ebu Cehil ile güçlendir"</text>\n  <text x="378" y="138" font-size="11" fill="#334155">• Olay: Kız kardeşi Fâtıma ve eniştesi Saîd\'in</text>\n  <text x="378" y="154" font-size="11" fill="#334155">  evinde Tâhâ suresinin ilk ayetlerinden</text>\n  <text x="378" y="170" font-size="11" fill="#334155">  etkilenip Dârülerkam\'da iman etmesi</text>\n  <text x="517" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Lakabı: El-Fârûk (Hak ile batılı ayıran)</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Sonuç: Kâbe\'de ilk kez açıktan namaz!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
